        Arc::from(store_factories.load_index_store(settings, &repo_path.join("index"))?);
    let submodule_store = Arc::from(
        store_factories.load_submodule_store(settings, &repo_path.join("submodule_store"))?,
    );
    Ok(Self {
        settings: settings.clone(),
        store,
        op_store,
        op_heads_store,
        index_store,
        submodule_store,
    })
}

