// first line and continue. With no subcommand, the banner is
// the whole invocation. Uniform `BANNER` (not the
// `vc-x1-<sub>` form clap's `propagate_version` would print)
// — the version is the binary's regardless of which
// subcommand it routes to.
if cli.version {
    log::info!("{BANNER}");
}

let Some(cmd) = cli.command else {
    // No subcommand. If `-V` was set the banner has already
    // printed, so follow it with the rest of the version
    // report and exit success; otherwise mirror clap's "a
    // subcommand is required" error by printing usage and
    // exiting non-zero. The report is only for the bare `-V`
    // invocation: as a rider on a subcommand `-V` stays one
    // banner line, so it neither loads a workspace nor
    // changes what scripts capturing it already see.
    if cli.version {
        for line in version::report(BANNER).into_iter().skip(1) {
            log::info!("{line}");
        }
        return ExitCode::SUCCESS;
    }
    let mut cmd = cli_with_banner();
    let _ = cmd.print_help();
    return ExitCode::FAILURE;
};

